"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { ProtocolVersion } from "@uniswap/client-pools/dist/pools/v1/types_pb";
const V2_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api";
const V3_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api";
const V2_POOL_QUERY = `
  query GetV2Pool($poolAddress: String!) {
    pair(id: $poolAddress) {
      id
      token0 {
        id
        symbol
        name
        decimals
      }
      token1 {
        id
        symbol
        name
        decimals
      }
      reserve0
      reserve1
      reserveUSD
      totalSupply
      volumeUSD
      txCount
      stable
      createdAtTimestamp
      createdAtBlockNumber
    }
  }
`;
const V3_POOL_QUERY = `
  query GetV3Pool($poolAddress: String!) {
    pool(id: $poolAddress) {
      id
      token0 {
        id
        symbol
        name
        decimals
      }
      token1 {
        id
        symbol
        name
        decimals
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
      volumeUSD
      txCount
      createdAtTimestamp
      createdAtBlockNumber
    }
  }
`;
async function fetchPoolFromSubgraph(subgraphUrl, query, poolAddress) {
  try {
    const response = await fetch(subgraphUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        query,
        variables: { poolAddress: poolAddress.toLowerCase() }
      })
    });
    const data = await response.json();
    if (data.errors) {
      console.error("Subgraph errors:", data.errors);
      return null;
    }
    return data.data?.pair || data.data?.pool || null;
  } catch (error) {
    console.error("Failed to fetch pool from subgraph:", error);
    return null;
  }
}
function transformV2Pool(pool) {
  return {
    idOrAddress: pool.id,
    feeTier: 3e3,
    // V2 pools have 0.3% fee
    txCount: parseInt(pool.txCount || "0"),
    protocolVersion: ProtocolVersion.V2,
    token0: {
      id: pool.token0.id,
      symbol: pool.token0.symbol,
      name: pool.token0.name,
      decimals: parseInt(pool.token0.decimals)
    },
    tvlToken0: parseFloat(pool.reserve0 || "0"),
    token1: {
      id: pool.token1.id,
      symbol: pool.token1.symbol,
      name: pool.token1.name,
      decimals: parseInt(pool.token1.decimals)
    },
    tvlToken1: parseFloat(pool.reserve1 || "0"),
    volumeUSD24H: parseFloat(pool.volumeUSD || "0"),
    tvlUSD: parseFloat(pool.reserveUSD || "0")
  };
}
function transformV3Pool(pool) {
  const tickSpacing = parseInt(pool.tickSpacing);
  let feeTier = 3e3;
  const TICK_SPACING_TO_FEE = {
    1: 100,
    // 0.01%
    50: 500,
    // 0.05%
    100: 500,
    // 0.05%
    200: 3e3,
    // 0.3%
    2e3: 1e4
    // 1%
  };
  if (tickSpacing in TICK_SPACING_TO_FEE) {
    feeTier = TICK_SPACING_TO_FEE[tickSpacing];
  }
  return {
    idOrAddress: pool.id,
    feeTier,
    txCount: parseInt(pool.txCount || "0"),
    protocolVersion: ProtocolVersion.V3,
    tickSpacing,
    token0: {
      id: pool.token0.id,
      symbol: pool.token0.symbol,
      name: pool.token0.name,
      decimals: parseInt(pool.token0.decimals)
    },
    tvlToken0: parseFloat(pool.totalValueLockedToken0 || "0"),
    token1: {
      id: pool.token1.id,
      symbol: pool.token1.symbol,
      name: pool.token1.name,
      decimals: parseInt(pool.token1.decimals)
    },
    tvlToken1: parseFloat(pool.totalValueLockedToken1 || "0"),
    volumeUSD24H: parseFloat(pool.volumeUSD || "0"),
    tvlUSD: parseFloat(pool.totalValueLockedUSD || "0")
  };
}
export function useAbstractPoolData(poolAddress, chainId = UniverseChainId.Sepolia) {
  const query = useQuery({
    queryKey: ["abstract-pool", poolAddress, chainId],
    queryFn: async () => {
      if (!poolAddress) {
        throw new Error("Pool address is required");
      }
      const v2Pool = await fetchPoolFromSubgraph(V2_SUBGRAPH_URL, V2_POOL_QUERY, poolAddress);
      if (v2Pool) {
        return transformV2Pool(v2Pool);
      }
      const v3Pool = await fetchPoolFromSubgraph(V3_SUBGRAPH_URL, V3_POOL_QUERY, poolAddress);
      if (v3Pool) {
        return transformV3Pool(v3Pool);
      }
      throw new Error("Pool not found in V2 or V3 subgraphs");
    },
    enabled: !!poolAddress,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    retry: 2
  });
  return {
    loading: query.isLoading,
    error: !!query.error,
    data: query.data
  };
}
